// The TypeScript core must decode pen packets exactly like NeoLAB's official SDK (the one the Obsidian plugin uses).
// tools/vectors.json: packets generated by tools/make_vectors.py, randomly split like Bluetooth notifications.
// tools/expected.json: what the official SDK makes of them (tools/ts_reference.ts).
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";
import { fromBase64, toBase64 } from "../src/core/bytes";
import { pageId } from "../src/core/models";
import { PenEvent, PenParser, PenRequest } from "../src/core/protocol";

const tools = join(__dirname, "..", "tools");
const r2 = (n: number) => Math.round(n * 100) / 100;
const hex = (h: string) => Uint8Array.from(h.match(/../g)!.map((x) => parseInt(x, 16)));
const toHex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");

function normalize(e: PenEvent): any[] {
  switch (e.type) {
    case "version": return [{ version: [e.version.deviceName, e.version.firmware, e.version.protocolVersion] }];
    case "settings": return [{ settings: [e.settings.locked, e.settings.battery, e.settings.maxForce, e.settings.usedMemory] }];
    case "noteList": return [{ notes: e.notes.map((n) => [n.section, n.owner, n.note]) }];
    case "pageList": return [{ pages: [e.section, e.owner, e.note, e.pages] }];
    case "offlineStart": return [{ start: [e.strokes, e.bytes] }];
    case "offlineFailure": return [{ failure: true }];
    case "powerOff": return [{ powerOff: true }];
    case "offlineChunk": return e.strokes.map(({ key, stroke: s }) => ({ offline: pageId(key), t: s.t, tip: s.tip, color: s.color, pts: s.pts.map(r2) }));
    // the official SDK's live filter always drops the first point of a stroke (side effect of its placeholder
    // pen-down with x = -1): we keep it, so it's removed here before comparing
    case "liveStroke": return [{ live: pageId(e.key), pts: e.stroke.pts.slice(3).map(r2) }];
    default: return [];
  }
}

// the official SDK unzips packets in parallel and may deliver offline strokes in another order: compare sorted by time
const sortKey = (e: any) => (e.offline ? `o${String(e.t).padStart(20, "0")}` : "");
const sorted = (a: any[]) => a.map((e, i) => [e, i] as const).sort((x, y) => (sortKey(x[0]) < sortKey(y[0]) ? -1 : sortKey(x[0]) > sortKey(y[0]) ? 1 : x[1] - y[1])).map((x) => x[0]);
const canon = (o: any): string => JSON.stringify(o, Object.keys(o).sort());

test("same results as the official SDK on 16 packet vectors", () => {
  const vectors = JSON.parse(readFileSync(join(tools, "vectors.json"), "utf8")) as { name: string; chunks: string[] }[];
  const expected = JSON.parse(readFileSync(join(tools, "expected.json"), "utf8")) as Record<string, any[]>;
  assert.equal(vectors.length, 16);
  for (const v of vectors) {
    const parser = new PenParser();
    const got: any[] = [];
    for (const h of v.chunks) for (const e of parser.feed(hex(h))) got.push(...normalize(e));
    for (const e of parser.flushLive()) got.push(...normalize(e));
    const want = expected[v.name].map((e) => {
      if (e.live === undefined) return e;
      const { t, ...rest } = e; // the pen-down time of "old style" live strokes doesn't go through the SDK
      return rest;
    });
    assert.equal(got.length, want.length, `${v.name}: number of events`);
    const a = sorted(got), b = sorted(want);
    for (let i = 0; i < a.length; i++) assert.equal(canon(a[i]), canon(b[i]), v.name);
  }
});

test("requests are byte-identical to the official SDK", () => {
  const want = JSON.parse(readFileSync(join(tools, "requests.json"), "utf8")) as Record<string, string>;
  const got: Record<string, Uint8Array> = {
    version: PenRequest.version(),
    penStatus: PenRequest.penStatus(),
    password: PenRequest.password("1234"),
    setTime: PenRequest.setTime(1792371234567),
    onlineAll: PenRequest.onlineAllNotes(),
    noteList: PenRequest.noteList(),
    pageList: PenRequest.pageList(3, 27, 746),
    pageListEsc: PenRequest.pageList(0xc1, 0x7dc0c1, 0xc0),
    offlineData: PenRequest.offlineData(3, 27, 746, [9], false),
    offlineDataDelete: PenRequest.offlineData(3, 27, 746, [5, 6, 0xc0], true),
    ack: PenRequest.offlineAck(0xc1),
    ackEnd: PenRequest.offlineAck(3, true, true),
  };
  assert.deepEqual(Object.keys(got).sort(), Object.keys(want).sort());
  for (const [k, b] of Object.entries(got)) assert.equal(toHex(b), want[k], k);
});

test("base64 round trip (bytes from the native module)", () => {
  for (let n = 0; n < 40; n++) {
    const b = Uint8Array.from({ length: n }, (_, i) => (i * 37 + n) & 0xff);
    assert.equal(toBase64(b), Buffer.from(b).toString("base64"));
    assert.deepEqual(fromBase64(Buffer.from(b).toString("base64")), b);
  }
});
